subroutine ESD_design_points ( order, n, x )

! Equivalent for the ESD of the subroutine design_points in sphere_design_rule.f90
  
    implicit none

  integer ( kind = 4 ) n
  integer ( kind = 4 ) order
  real ( kind = 8 ) x(n)

  if ( order == 1 ) then
    call ESD_001_00003 ( x )
  elseif ( order == 2 ) then
    call ESD_002_00006 ( x )
  elseif ( order == 3 ) then
    call ESD_003_00008 ( x )
  elseif ( order == 4 ) then
    call ESD_004_00014 ( x )
  elseif ( order == 5 ) then
