subroutine ESD_design_closer_order ( n, order, ndes )

! Equivalent for the ESD of the subroutine design_closer_order in sphere_design_rule.f90

  implicit none

  integer ( kind = 4 ) n,ndes,dmin
  integer ( kind = 4 ) order
  integer ( kind = 4 ),dimension(43) :: all_avail_n
  integer ( kind = 4 ), dimension(43) :: d
  
  all_avail_n = [3,6,8,14,18,26,32,42,50,62,72,86,98,114,128,146,163,182, &
                201,222,243,266,289,314,339,366,393,422,451,482,513,546,  &
                579,614,649,686,723,762,801,842,883,926,3282];
                
  d = all_avail_n - n;
  order = minloc(d,1,mask=(d .ge. 0));
  ndes = all_avail_n(order);
  
  if (n > 1000) then
    order = 80; 
    ndes = 3282
  end if

  return
end    
    
